using Jig.Domain;

namespace Jig.Application;

/// <summary>The order use-cases: list, get, and save. Returns Result envelopes so
/// expected failures travel as data, not exceptions.</summary>
/// <capability>api.order-service</capability>
/// <intent>One cohesive place for the order use-case logic, independent of transport and database.</intent>
/// <reuse>Inject OrderService into endpoints; it speaks IOrderRepository, never EF Core directly.</reuse>
public sealed class OrderService
{
    private readonly IOrderRepository _repo;

    public OrderService(IOrderRepository repo) => _repo = repo;

    public async Task<Result<IReadOnlyList<Order>>> ListAsync(CancellationToken ct)
        => Result<IReadOnlyList<Order>>.Success(await _repo.GetAllAsync(ct));

    public async Task<Result<Order>> GetAsync(Guid id, CancellationToken ct)
    {
        var order = await _repo.GetByIdAsync(id, ct);
        return order is null ? Error.NotFound($"Order {id} was not found.") : order;
    }

    public async Task<Result<Order>> SaveAsync(Guid? id, string reference, decimal total, CancellationToken ct)
    {
        var byReference = await _repo.GetByReferenceAsync(reference, ct);
        if (byReference is not null && byReference.Id != id)
            return Error.Conflict($"Reference {reference} is already in use.");

        Order order;
        if (id is Guid existingId)
        {
            var current = await _repo.GetByIdAsync(existingId, ct);
            if (current is null)
                return Error.NotFound($"Order {existingId} was not found.");
            current.Reference = reference;
            current.Total = total;
            order = current;
        }
        else
        {
            order = new Order { Id = Guid.NewGuid(), Reference = reference, Total = total };
        }

        return await _repo.UpsertAsync(order, ct);
    }
}

