import { Injectable, inject, signal } from '@angular/core';
import type { SaveOrderInput, OrderDto } from '../../contracts';
import type { AppError } from '../../transport';
import { OrderOperations } from '../../operations/order.operations';

/**
 * ViewModel for the orders slice. Exposes signals only; the View binds to them
 * and never touches a facade or transport. Depends on OrderOperations, which speaks
 * operations, so this class is identical regardless of which transport is underneath.
 */
@Injectable()
export class OrderListViewModel {
  private readonly ops = inject(OrderOperations);

  readonly orders = signal<OrderDto[]>([]);
  readonly loading = signal(false);
  readonly error = signal<AppError | null>(null);
  readonly formOpen = signal(false);
  readonly saving = signal(false);

  openForm(): void { this.formOpen.set(true); }

  load(): void {
    this.loading.set(true);
    this.error.set(null);
    this.ops.list().subscribe({
      next: (orders) => {
        this.orders.set(orders);
        this.loading.set(false);
      },
      error: (err: AppError) => {
        this.error.set(err);
        this.loading.set(false);
      },
    });
  }

  save(input: SaveOrderInput): void {
    this.error.set(null);
    this.saving.set(true);
    this.ops.save(input).subscribe({
      next: () => { this.saving.set(false); this.formOpen.set(false); this.load(); },
      error: (err: AppError) => { this.saving.set(false); this.error.set(err); },
    });
  }
}

