import { OrderOperations } from './order.operations';
import { Transport } from '../transport';
import type { OperationName, Req, Res } from '../contracts';

/** Records which operations the facade asks the transport for. */
class RecordingTransport extends Transport {
  readonly calls: Array<{ op: string; payload: unknown }> = [];
  request<K extends OperationName>(op: K, payload: Req<K>): Observable<Res<K>> {
    this.calls.push({ op, payload });
    return of(undefined as unknown as Res<K>);
  }
}

function setup() {
  const transport = new RecordingTransport();
  TestBed.resetTestingModule();
  TestBed.configureTestingModule({ providers: [{ provide: Transport, useValue: transport }] });
  return { transport, ops: TestBed.inject(OrderOperations) };
}

describe('OrderOperations', () => {
  it('list() asks for the orders.list operation', async () => {
    const { transport, ops } = setup();
    await firstValueFrom(ops.list());
    expect(transport.calls).toEqual([{ op: 'orders.list', payload: {} }]);
  });

  it('get() asks for orders.get with the id', async () => {
    const { transport, ops } = setup();
    await firstValueFrom(ops.get('abc'));
    expect(transport.calls).toEqual([{ op: 'orders.get', payload: { id: 'abc' } }]);
  });

  it('save() asks for orders.save with the order body', async () => {
    const { transport, ops } = setup();
    await firstValueFrom(ops.save({ reference: 'alpha', total: 1 }));
    expect(transport.calls).toEqual([{ op: 'orders.save', payload: { reference: 'alpha', total: 1 } }]);
  });
});

