//! Order store for the desktop client. Holds the same order use-cases the
//! .NET API does, so the frontend behaves identically whether it talks to the native
//! store or to the API over HTTP. Command adapters are thin wrappers over this; the
//! logic is here and unit-tested in isolation.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Mutex;
use uuid::Uuid;

/// The order shape crossing the wire. Serializes to the same JSON as the .NET
/// OrderResponse, so the operation registry's res type fits both.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Order {
    pub id: String,
    pub reference: String,
    pub total: f64,
}

/// An expected failure. Maps to a rejected invoke on the wire.
#[derive(Debug, PartialEq)]
pub enum StoreError {
    NotFound(String),
    Conflict(String),
}

impl std::fmt::Display for StoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StoreError::NotFound(m) | StoreError::Conflict(m) => write!(f, "{m}"),
        }
    }
}

/// In-memory order store. A template default: swap the Mutex<HashMap> for SQLite or
/// a file store without changing the commands or the frontend.
///
/// @capability shell.order-store
/// @intent The desktop client's order use-cases, mirroring the API so both wires agree.
/// @reuse Manage one OrderStore in the app state; commands delegate to it.
#[derive(Default)]
pub struct OrderStore {
    orders: Mutex<HashMap<String, Order>>,
}

impl OrderStore {
    pub fn list(&self) -> Vec<Order> {
        let mut all: Vec<Order> = self.orders.lock().unwrap().values().cloned().collect();
        all.sort_by(|a, b| a.reference.partial_cmp(&b.reference).unwrap_or(std::cmp::Ordering::Equal).then_with(|| a.id.cmp(&b.id)));
        all
    }

    pub fn get(&self, id: &str) -> Result<Order, StoreError> {
        self.orders
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| StoreError::NotFound(format!("Order {id} was not found.")))
    }

    pub fn save(&self, id: Option<String>, reference: String, total: f64) -> Result<Order, StoreError> {
        let mut orders = self.orders.lock().unwrap();

        if let Some(existing) = orders.values().find(|x| x.reference == reference) {
            if Some(&existing.id) != id.as_ref() {
                return Err(StoreError::Conflict(format!("Reference {reference} is already in use.")));
            }
        }

        match id {
            Some(id) => {
                let order = orders
                    .get_mut(&id)
                    .ok_or_else(|| StoreError::NotFound(format!("Order {id} was not found.")))?;
                order.reference = reference;
                order.total = total;
                Ok(order.clone())
            }
            None => {
                let order = Order { id: Uuid::new_v4().to_string(), reference, total };
                orders.insert(order.id.clone(), order.clone());
                Ok(order)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_is_empty_on_a_fresh_store() {
        let store = OrderStore::default();
        assert_eq!(store.list(), vec![]);
    }

    #[test]
    fn save_creates_a_order_with_an_id() {
        let store = OrderStore::default();
        let order = store.save(None, "alpha".to_string(), 1.0).unwrap();
        assert!(!order.id.is_empty());
        assert_eq!(order.reference, "alpha");
        assert_eq!(store.list().len(), 1);
    }

    #[test]
    fn get_unknown_id_is_not_found() {
        let store = OrderStore::default();
        assert_eq!(
            store.get("missing"),
            Err(StoreError::NotFound("Order missing was not found.".into()))
        );
    }

    #[test]
    fn save_then_get_roundtrips() {
        let store = OrderStore::default();
        let created = store.save(None, "alpha".to_string(), 1.0).unwrap();
        assert_eq!(store.get(&created.id).unwrap(), created);
    }

    #[test]
    fn save_duplicate_reference_on_a_different_order_is_conflict() {
        let store = OrderStore::default();
        store.save(None, "alpha".to_string(), 1.0).unwrap();
        let result = store.save(None, "alpha".to_string(), 2.0);
        assert!(matches!(result, Err(StoreError::Conflict(_))));
    }

    #[test]
    fn save_update_keeps_the_same_reference_without_conflict() {
        let store = OrderStore::default();
        let created = store.save(None, "alpha".to_string(), 1.0).unwrap();
        let updated = store
            .save(Some(created.id.clone()), "alpha".to_string(), 2.0)
            .unwrap();
        assert_eq!(updated.id, created.id);
        assert_eq!(updated.total, 2.0);
    }

    #[test]
    fn save_update_of_unknown_id_is_not_found() {
        let store = OrderStore::default();
        let result = store.save(Some("ghost".to_string()), "bravo".to_string(), 2.0);
        assert!(matches!(result, Err(StoreError::NotFound(_))));
    }
}

