{
    public Guid? Id { get; set; }
    public string Reference { get; set; } = "";
    public decimal Total { get; set; }
}

using FastEndpoints;
using Jig.Application;

namespace Jig.Api.Orders;

/// <summary>orders.list — GET /orders. Returns every order.</summary>
public sealed class ListOrdersEndpoint : EndpointWithoutRequest<IEnumerable<OrderResponse>>
{
    private readonly OrderService _orders;

    public ListOrdersEndpoint(OrderService orders) => _orders = orders;

    public override void Configure()
    {
        Get("/orders");
        AllowAnonymous();
    }

    public override async Task HandleAsync(CancellationToken ct)
    {
        var result = await _orders.ListAsync(ct);
        await Send.OkAsync(result.Value!.Select(x => x.ToResponse()), ct);
    }
}

