using Jig.Application;
using Jig.Domain;
using Microsoft.EntityFrameworkCore;

namespace Jig.Infrastructure;

/// <summary>EF Core implementation of the order persistence port.</summary>
/// <capability>api.order-repository</capability>
/// <intent>The only place that touches EF Core for orders; the application never sees a DbContext.</intent>
/// <reuse>Registered for IOrderRepository by AddInfrastructure; do not new it up directly.</reuse>
public sealed class OrderRepository : IOrderRepository
{
    private readonly JigDbContext _db;

    public OrderRepository(JigDbContext db) => _db = db;

    public async Task<IReadOnlyList<Order>> GetAllAsync(CancellationToken ct)
        => (await _db.Orders.AsNoTracking().ToListAsync(ct)).OrderBy(x => x.Reference, StringComparer.Ordinal).ThenBy(x => x.Id).ToList();

    public Task<Order?> GetByIdAsync(Guid id, CancellationToken ct)
        => _db.Orders.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);

    public Task<Order?> GetByReferenceAsync(string reference, CancellationToken ct)
        => _db.Orders.AsNoTracking().FirstOrDefaultAsync(x => x.Reference == reference, ct);

    public async Task<Order> UpsertAsync(Order order, CancellationToken ct)
    {
        var existing = await _db.Orders.FirstOrDefaultAsync(x => x.Id == order.Id, ct);
        if (existing is null)
        {
            _db.Orders.Add(order);
        }
        else
        {
            existing.Reference = order.Reference;
            existing.Total = order.Total;
        }

        await _db.SaveChangesAsync(ct);
        return existing ?? order;
    }
}

