using Shouldly;
using Jig.Domain;

namespace Jig.Application.Tests;

public class OrderServiceTests
{
    private readonly IOrderRepository _repo = A.Fake<IOrderRepository>();
    private OrderService Sut() => new(_repo);

    [Fact]
    public async Task ListAsync_returns_all_orders_as_success()
    {
        var orders = new List<Order> { new() { Id = Guid.NewGuid(), Reference = "alpha", Total = 1m } };
        A.CallTo(() => _repo.GetAllAsync(A<CancellationToken>._)).Returns(orders);

        var result = await Sut().ListAsync(CancellationToken.None);

        result.IsSuccess.ShouldBeTrue();
        result.Value.ShouldBe(orders);
    }

    [Fact]
    public async Task GetAsync_unknown_id_returns_NotFound()
    {
        A.CallTo(() => _repo.GetByIdAsync(A<Guid>._, A<CancellationToken>._)).Returns((Order?)null);

        var result = await Sut().GetAsync(Guid.NewGuid(), CancellationToken.None);

        result.IsSuccess.ShouldBeFalse();
        result.Error!.Kind.ShouldBe(ErrorKind.NotFound);
    }

    [Fact]
    public async Task GetAsync_known_id_returns_order()
    {
        var order = new Order { Id = Guid.NewGuid(), Reference = "bravo", Total = 2m };
        A.CallTo(() => _repo.GetByIdAsync(order.Id, A<CancellationToken>._)).Returns(order);

        var result = await Sut().GetAsync(order.Id, CancellationToken.None);

        result.IsSuccess.ShouldBeTrue();
        result.Value.ShouldBe(order);
    }

    [Fact]
    public async Task SaveAsync_new_order_creates_and_returns_it()
    {
        A.CallTo(() => _repo.GetByReferenceAsync(A<string>._, A<CancellationToken>._)).Returns((Order?)null);
        A.CallTo(() => _repo.UpsertAsync(A<Order>._, A<CancellationToken>._))
            .ReturnsLazily((Order x, CancellationToken _) => x);

        var result = await Sut().SaveAsync(null, "alpha", 1m, CancellationToken.None);

        result.IsSuccess.ShouldBeTrue();
        result.Value!.Id.ShouldNotBe(Guid.Empty);
        result.Value.Reference.ShouldBe("alpha");
        A.CallTo(() => _repo.UpsertAsync(A<Order>.That.Matches(x => x.Reference == "alpha"), A<CancellationToken>._))
            .MustHaveHappenedOnceExactly();
    }

    [Fact]
    public async Task SaveAsync_duplicate_reference_returns_Conflict()
    {
        var other = new Order { Id = Guid.NewGuid(), Reference = "bravo", Total = 2m };
        A.CallTo(() => _repo.GetByReferenceAsync("bravo", A<CancellationToken>._)).Returns(other);

        var result = await Sut().SaveAsync(null, "bravo", 2m, CancellationToken.None);

        result.IsSuccess.ShouldBeFalse();
        result.Error!.Kind.ShouldBe(ErrorKind.Conflict);
        A.CallTo(() => _repo.UpsertAsync(A<Order>._, A<CancellationToken>._)).MustNotHaveHappened();
    }

    [Fact]
    public async Task SaveAsync_update_of_unknown_id_returns_NotFound()
    {
        A.CallTo(() => _repo.GetByReferenceAsync(A<string>._, A<CancellationToken>._)).Returns((Order?)null);
        A.CallTo(() => _repo.GetByIdAsync(A<Guid>._, A<CancellationToken>._)).Returns((Order?)null);

        var result = await Sut().SaveAsync(Guid.NewGuid(), "bravo", 2m, CancellationToken.None);

        result.IsSuccess.ShouldBeFalse();
        result.Error!.Kind.ShouldBe(ErrorKind.NotFound);
    }
}

