namespace Jig.Api.Tests;

public class OrdersEndpointTests : IClassFixture<ApiFixture>
{
    private readonly HttpClient _client;

    public OrdersEndpointTests(ApiFixture app) => _client = app.Client;

    private static object NewOrder() => new { reference = $"alpha-{Guid.NewGuid():N}", total = 1m };

    [Fact]
    public async Task list_returns_200()
    {
        var res = await _client.GetAsync("/orders");
        res.StatusCode.ShouldBe(HttpStatusCode.OK);
    }

    [Fact]
    public async Task save_then_get_roundtrips_the_order()
    {
        var post = await _client.PostAsJsonAsync("/orders", NewOrder());
        post.StatusCode.ShouldBe(HttpStatusCode.OK);
        var created = await post.Content.ReadFromJsonAsync<OrderResponse>();
        created!.Id.ShouldNotBe(Guid.Empty);

        var get = await _client.GetAsync($"/orders/{created.Id}");
        get.StatusCode.ShouldBe(HttpStatusCode.OK);
        var fetched = await get.Content.ReadFromJsonAsync<OrderResponse>();
        fetched!.Reference.ShouldBe(created.Reference);
    }

    [Fact]
    public async Task save_with_invalid_body_returns_400()
    {
        var res = await _client.PostAsJsonAsync("/orders", new { reference = "", total = 0m });
        res.StatusCode.ShouldBe(HttpStatusCode.BadRequest);
    }

    [Fact]
    public async Task get_unknown_id_returns_404()
    {
        var res = await _client.GetAsync($"/orders/{Guid.NewGuid()}");
        res.StatusCode.ShouldBe(HttpStatusCode.NotFound);
    }

    [Fact]
    public async Task save_duplicate_reference_returns_409()
    {
        var reference = $"alpha-{Guid.NewGuid():N}";
        (await _client.PostAsJsonAsync("/orders", new { total = 1m, reference })).EnsureSuccessStatusCode();

        var res = await _client.PostAsJsonAsync("/orders", new { total = 2m, reference });
        res.StatusCode.ShouldBe(HttpStatusCode.Conflict);
    }
}

