import { Injectable, inject } from '@angular/core';
import type { Observable } from 'rxjs';
import type { SaveOrderInput, OrderDto } from '../contracts';
import { Transport } from '../transport';

/**
 * The order operations facade: speaks operations, never URLs or command names.
 * Identical across both wires because it only ever talks to the Transport port.
 *
 * @capability operations.order
 * @intent Domain-facing order data access that is oblivious to the transport underneath.
 * @reuse Inject OrderOperations from ViewModels; copy this shape for new feature facades.
 */
@Injectable({ providedIn: 'root' })
export class OrderOperations {
  private readonly transport = inject(Transport);

  list(): Observable<OrderDto[]> {
    return this.transport.request('orders.list', {});
  }

  get(id: string): Observable<OrderDto> {
    return this.transport.request('orders.get', { id });
  }

  save(order: SaveOrderInput): Observable<OrderDto> {
    return this.transport.request('orders.save', order);
  }
}

