import { Component, output } from '@angular/core';
import { SchemaForm } from '../../forms/schema-form';
import { orderFormSchema, type OrderFormModel } from './order-form.schema';

/**
 * The form that adds orders. Renders entirely through SchemaForm: the schema
 * carries every field's shape, validation, and control kind, so this component
 * wires nothing per field and holds no form state of its own.
 */
@Component({
  selector: 'app-order-form',
  imports: [SchemaForm],
  template: `<app-schema-form [schema]="orderFormSchema" submitLabel="Add order" (submitted)="onSubmitted($event)" />`,
})
export class OrderForm {
  protected readonly orderFormSchema = orderFormSchema;
  readonly saved = output<OrderFormModel>();

  // SchemaForm.submitted is output<Record<string, unknown>> because it renders a
  // schema it only knows about at runtime; Angular templates have no `as`, so the
  // narrowing to this form's own model has to happen here rather than inline in the
  // binding above. It only ever emits after safeParse against orderFormSchema (the
  // very schema passed to it above), so the payload is this model by construction.
  protected onSubmitted(value: Record<string, unknown>): void {
    this.saved.emit(value as OrderFormModel);
  }
}

import { computed, inject, provideAppInitializer, type EnvironmentProviders } from '@angular/core';
import { MenuService, navigateCommand, type Command } from '../../menu';
import { OrderListViewModel } from './order-list.view-model';

/** The orders slice's action command: opens the create form, disabled mid-save. */
export function newOrderCommand(vm: OrderListViewModel): Command {
  return {
    id: 'new-order',
    label: 'new order',
    icon: 'lucidePlus',
    canExecute: computed(() => !vm.saving()),
    execute: () => vm.openForm(),
  };
}

/**
 * Registers the orders NAV command app-wide (it must be reachable from anywhere,
 * so it lives for the app's lifetime — provideAppInitializer runs in the root
 * injection context). The ACTION command is registered view-scoped in the view.
 */
export function registerOrdersNav(menu: MenuService): void {
  menu.register('sidebar', navigateCommand({ id: 'nav-orders', label: 'orders', icon: 'lucideBox', route: '/orders' }));
}

export function provideOrdersMenu(): EnvironmentProviders {
  return provideAppInitializer(() => registerOrdersNav(inject(MenuService)));
}

