using Jig.Domain;

namespace Jig.Application;

/// <summary>The flag use-cases: list, get, and save. Returns Result envelopes so
/// expected failures travel as data, not exceptions.</summary>
/// <capability>api.flag-service</capability>
/// <intent>One cohesive place for the flag use-case logic, independent of transport and database.</intent>
/// <reuse>Inject FlagService into endpoints; it speaks IFlagRepository, never EF Core directly.</reuse>
public sealed class FlagService
{
    private readonly IFlagRepository _repo;

    public FlagService(IFlagRepository repo) => _repo = repo;

    public async Task<Result<IReadOnlyList<Flag>>> ListAsync(CancellationToken ct)
        => Result<IReadOnlyList<Flag>>.Success(await _repo.GetAllAsync(ct));

    public async Task<Result<Flag>> GetAsync(Guid id, CancellationToken ct)
    {
        var flag = await _repo.GetByIdAsync(id, ct);
        return flag is null ? Error.NotFound($"Flag {id} was not found.") : flag;
    }

    public async Task<Result<Flag>> SaveAsync(Guid? id, bool enabled, bool archived, CancellationToken ct)
    {
        Flag flag;
        if (id is Guid existingId)
        {
            var current = await _repo.GetByIdAsync(existingId, ct);
            if (current is null)
                return Error.NotFound($"Flag {existingId} was not found.");
            current.Enabled = enabled;
            current.Archived = archived;
            flag = current;
        }
        else
        {
            flag = new Flag { Id = Guid.NewGuid(), Enabled = enabled, Archived = archived };
        }

        return await _repo.UpsertAsync(flag, ct);
    }
}

