using Jig.Application;
using Jig.Domain;
using Microsoft.EntityFrameworkCore;

namespace Jig.Infrastructure;

/// <summary>EF Core implementation of the flag persistence port.</summary>
/// <capability>api.flag-repository</capability>
/// <intent>The only place that touches EF Core for flags; the application never sees a DbContext.</intent>
/// <reuse>Registered for IFlagRepository by AddInfrastructure; do not new it up directly.</reuse>
public sealed class FlagRepository : IFlagRepository
{
    private readonly JigDbContext _db;

    public FlagRepository(JigDbContext db) => _db = db;

    public async Task<IReadOnlyList<Flag>> GetAllAsync(CancellationToken ct)
        => (await _db.Flags.AsNoTracking().ToListAsync(ct)).OrderBy(x => x.Enabled).ThenBy(x => x.Id).ToList();

    public Task<Flag?> GetByIdAsync(Guid id, CancellationToken ct)
        => _db.Flags.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);

    public async Task<Flag> UpsertAsync(Flag flag, CancellationToken ct)
    {
        var existing = await _db.Flags.FirstOrDefaultAsync(x => x.Id == flag.Id, ct);
        if (existing is null)
        {
            _db.Flags.Add(flag);
        }
        else
        {
            existing.Enabled = flag.Enabled;
            existing.Archived = flag.Archived;
        }

        await _db.SaveChangesAsync(ct);
        return existing ?? flag;
    }
}

