//! Flag store for the desktop client. Holds the same flag use-cases the
//! .NET API does, so the frontend behaves identically whether it talks to the native
//! store or to the API over HTTP. Command adapters are thin wrappers over this; the
//! logic is here and unit-tested in isolation.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Mutex;
use uuid::Uuid;

/// The flag shape crossing the wire. Serializes to the same JSON as the .NET
/// FlagResponse, so the operation registry's res type fits both.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Flag {
    pub id: String,
    pub enabled: bool,
    pub archived: bool,
}

/// An expected failure. Maps to a rejected invoke on the wire.
#[derive(Debug, PartialEq)]
pub enum StoreError {
    NotFound(String),
    Conflict(String),
}

impl std::fmt::Display for StoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StoreError::NotFound(m) | StoreError::Conflict(m) => write!(f, "{m}"),
        }
    }
}

/// In-memory flag store. A template default: swap the Mutex<HashMap> for SQLite or
/// a file store without changing the commands or the frontend.
///
/// @capability shell.flag-store
/// @intent The desktop client's flag use-cases, mirroring the API so both wires agree.
/// @reuse Manage one FlagStore in the app state; commands delegate to it.
#[derive(Default)]
pub struct FlagStore {
    flags: Mutex<HashMap<String, Flag>>,
}

impl FlagStore {
    pub fn list(&self) -> Vec<Flag> {
        let mut all: Vec<Flag> = self.flags.lock().unwrap().values().cloned().collect();
        all.sort_by(|a, b| a.enabled.partial_cmp(&b.enabled).unwrap_or(std::cmp::Ordering::Equal).then_with(|| a.id.cmp(&b.id)));
        all
    }

    pub fn get(&self, id: &str) -> Result<Flag, StoreError> {
        self.flags
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| StoreError::NotFound(format!("Flag {id} was not found.")))
    }

    pub fn save(&self, id: Option<String>, enabled: bool, archived: bool) -> Result<Flag, StoreError> {
        let mut flags = self.flags.lock().unwrap();

        match id {
            Some(id) => {
                let flag = flags
                    .get_mut(&id)
                    .ok_or_else(|| StoreError::NotFound(format!("Flag {id} was not found.")))?;
                flag.enabled = enabled;
                flag.archived = archived;
                Ok(flag.clone())
            }
            None => {
                let flag = Flag { id: Uuid::new_v4().to_string(), enabled, archived };
                flags.insert(flag.id.clone(), flag.clone());
                Ok(flag)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_is_empty_on_a_fresh_store() {
        let store = FlagStore::default();
        assert_eq!(store.list(), vec![]);
    }

    #[test]
    fn save_creates_a_flag_with_an_id() {
        let store = FlagStore::default();
        let flag = store.save(None, true, true).unwrap();
        assert!(!flag.id.is_empty());
        assert_eq!(flag.enabled, true);
        assert_eq!(store.list().len(), 1);
    }

    #[test]
    fn get_unknown_id_is_not_found() {
        let store = FlagStore::default();
        assert_eq!(
            store.get("missing"),
            Err(StoreError::NotFound("Flag missing was not found.".into()))
        );
    }

    #[test]
    fn save_then_get_roundtrips() {
        let store = FlagStore::default();
        let created = store.save(None, true, true).unwrap();
        assert_eq!(store.get(&created.id).unwrap(), created);
    }

    #[test]
    fn save_update_of_unknown_id_is_not_found() {
        let store = FlagStore::default();
        let result = store.save(Some("ghost".to_string()), false, false);
        assert!(matches!(result, Err(StoreError::NotFound(_))));
    }
}

