/// <summary>Persistence port for stockItems. The application depends on this abstraction;
/// Infrastructure supplies the EF Core implementation.</summary>
/// <capability>api.stock-item-repository-port</capability>
/// <intent>The use-case layer owns the persistence contract it needs, not the database.</intent>
/// <reuse>Depend on IStockItemRepository from application services; implement it in Infrastructure only.</reuse>
public interface IStockItemRepository
{
    Task<IReadOnlyList<StockItem>> GetAllAsync(CancellationToken ct);
    Task<StockItem?> GetByIdAsync(Guid id, CancellationToken ct);
    Task<StockItem?> GetBySkuAsync(string sku, CancellationToken ct);
    Task<StockItem> UpsertAsync(StockItem stockItem, CancellationToken ct);
}

using Jig.Domain;

namespace Jig.Application;

/// <summary>The stockItem use-cases: list, get, and save. Returns Result envelopes so
/// expected failures travel as data, not exceptions.</summary>
/// <capability>api.stock-item-service</capability>
/// <intent>One cohesive place for the stockItem use-case logic, independent of transport and database.</intent>
/// <reuse>Inject StockItemService into endpoints; it speaks IStockItemRepository, never EF Core directly.</reuse>
public sealed class StockItemService
{
    private readonly IStockItemRepository _repo;

    public StockItemService(IStockItemRepository repo) => _repo = repo;

    public async Task<Result<IReadOnlyList<StockItem>>> ListAsync(CancellationToken ct)
        => Result<IReadOnlyList<StockItem>>.Success(await _repo.GetAllAsync(ct));

    public async Task<Result<StockItem>> GetAsync(Guid id, CancellationToken ct)
    {
        var stockItem = await _repo.GetByIdAsync(id, ct);
        return stockItem is null ? Error.NotFound($"StockItem {id} was not found.") : stockItem;
    }

    public async Task<Result<StockItem>> SaveAsync(Guid? id, decimal quantity, bool active, string sku, CancellationToken ct)
    {
        var bySku = await _repo.GetBySkuAsync(sku, ct);
        if (bySku is not null && bySku.Id != id)
            return Error.Conflict($"SKU {sku} is already in use.");

        StockItem stockItem;
        if (id is Guid existingId)
        {
            var current = await _repo.GetByIdAsync(existingId, ct);
            if (current is null)
                return Error.NotFound($"StockItem {existingId} was not found.");
            current.Quantity = quantity;
            current.Active = active;
            current.Sku = sku;
            stockItem = current;
        }
        else
        {
            stockItem = new StockItem { Id = Guid.NewGuid(), Quantity = quantity, Active = active, Sku = sku };
        }

        return await _repo.UpsertAsync(stockItem, ct);
    }
}

