using Jig.Application;
using Jig.Domain;
using Microsoft.EntityFrameworkCore;

namespace Jig.Infrastructure;

/// <summary>EF Core implementation of the stockItem persistence port.</summary>
/// <capability>api.stock-item-repository</capability>
/// <intent>The only place that touches EF Core for stockItems; the application never sees a DbContext.</intent>
/// <reuse>Registered for IStockItemRepository by AddInfrastructure; do not new it up directly.</reuse>
public sealed class StockItemRepository : IStockItemRepository
{
    private readonly JigDbContext _db;

    public StockItemRepository(JigDbContext db) => _db = db;

    public async Task<IReadOnlyList<StockItem>> GetAllAsync(CancellationToken ct)
        => (await _db.StockItems.AsNoTracking().ToListAsync(ct)).OrderBy(x => x.Quantity).ThenBy(x => x.Id).ToList();

    public Task<StockItem?> GetByIdAsync(Guid id, CancellationToken ct)
        => _db.StockItems.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);

    public Task<StockItem?> GetBySkuAsync(string sku, CancellationToken ct)
        => _db.StockItems.AsNoTracking().FirstOrDefaultAsync(x => x.Sku == sku, ct);

    public async Task<StockItem> UpsertAsync(StockItem stockItem, CancellationToken ct)
    {
        var existing = await _db.StockItems.FirstOrDefaultAsync(x => x.Id == stockItem.Id, ct);
        if (existing is null)
        {
            _db.StockItems.Add(stockItem);
        }
        else
        {
            existing.Quantity = stockItem.Quantity;
            existing.Active = stockItem.Active;
            existing.Sku = stockItem.Sku;
        }

        await _db.SaveChangesAsync(ct);
        return existing ?? stockItem;
    }
}

