//! StockItem store for the desktop client. Holds the same stock item use-cases the
//! .NET API does, so the frontend behaves identically whether it talks to the native
//! store or to the API over HTTP. Command adapters are thin wrappers over this; the
//! logic is here and unit-tested in isolation.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Mutex;
use uuid::Uuid;

/// The stock item shape crossing the wire. Serializes to the same JSON as the .NET
/// StockItemResponse, so the operation registry's res type fits both.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StockItem {
    pub id: String,
    pub quantity: f64,
    pub active: bool,
    pub sku: String,
}

/// An expected failure. Maps to a rejected invoke on the wire.
#[derive(Debug, PartialEq)]
pub enum StoreError {
    NotFound(String),
    Conflict(String),
}

impl std::fmt::Display for StoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StoreError::NotFound(m) | StoreError::Conflict(m) => write!(f, "{m}"),
        }
    }
}

/// In-memory stock item store. A template default: swap the Mutex<HashMap> for SQLite or
/// a file store without changing the commands or the frontend.
///
/// @capability shell.stock-item-store
/// @intent The desktop client's stock item use-cases, mirroring the API so both wires agree.
/// @reuse Manage one StockItemStore in the app state; commands delegate to it.
#[derive(Default)]
pub struct StockItemStore {
    stock_items: Mutex<HashMap<String, StockItem>>,
}

impl StockItemStore {
    pub fn list(&self) -> Vec<StockItem> {
        let mut all: Vec<StockItem> = self.stock_items.lock().unwrap().values().cloned().collect();
        all.sort_by(|a, b| a.quantity.partial_cmp(&b.quantity).unwrap_or(std::cmp::Ordering::Equal).then_with(|| a.id.cmp(&b.id)));
        all
    }

    pub fn get(&self, id: &str) -> Result<StockItem, StoreError> {
        self.stock_items
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| StoreError::NotFound(format!("StockItem {id} was not found.")))
    }

    pub fn save(&self, id: Option<String>, quantity: f64, active: bool, sku: String) -> Result<StockItem, StoreError> {
        let mut stock_items = self.stock_items.lock().unwrap();

        if let Some(existing) = stock_items.values().find(|x| x.sku == sku) {
            if Some(&existing.id) != id.as_ref() {
                return Err(StoreError::Conflict(format!("SKU {sku} is already in use.")));
            }
        }

        match id {
            Some(id) => {
                let stock_item = stock_items
                    .get_mut(&id)
                    .ok_or_else(|| StoreError::NotFound(format!("StockItem {id} was not found.")))?;
                stock_item.quantity = quantity;
                stock_item.active = active;
                stock_item.sku = sku;
                Ok(stock_item.clone())
            }
            None => {
                let stock_item = StockItem { id: Uuid::new_v4().to_string(), quantity, active, sku };
                stock_items.insert(stock_item.id.clone(), stock_item.clone());
                Ok(stock_item)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_is_empty_on_a_fresh_store() {
        let store = StockItemStore::default();
        assert_eq!(store.list(), vec![]);
    }

    #[test]
    fn save_creates_a_stock_item_with_an_id() {
        let store = StockItemStore::default();
        let stock_item = store.save(None, 1.0, true, "alpha".to_string()).unwrap();
        assert!(!stock_item.id.is_empty());
        assert_eq!(stock_item.quantity, 1.0);
        assert_eq!(store.list().len(), 1);
    }

    #[test]
    fn get_unknown_id_is_not_found() {
        let store = StockItemStore::default();
        assert_eq!(
            store.get("missing"),
            Err(StoreError::NotFound("StockItem missing was not found.".into()))
        );
    }

    #[test]
    fn save_then_get_roundtrips() {
        let store = StockItemStore::default();
        let created = store.save(None, 1.0, true, "alpha".to_string()).unwrap();
        assert_eq!(store.get(&created.id).unwrap(), created);
    }

    #[test]
    fn save_duplicate_sku_on_a_different_stock_item_is_conflict() {
        let store = StockItemStore::default();
        store.save(None, 1.0, true, "alpha".to_string()).unwrap();
        let result = store.save(None, 2.0, false, "alpha".to_string());
        assert!(matches!(result, Err(StoreError::Conflict(_))));
    }

    #[test]
    fn save_update_keeps_the_same_sku_without_conflict() {
        let store = StockItemStore::default();
        let created = store.save(None, 1.0, true, "alpha".to_string()).unwrap();
        let updated = store
            .save(Some(created.id.clone()), 2.0, false, "alpha".to_string())
            .unwrap();
        assert_eq!(updated.id, created.id);
        assert_eq!(updated.quantity, 2.0);
    }

    #[test]
    fn save_update_of_unknown_id_is_not_found() {
        let store = StockItemStore::default();
        let result = store.save(Some("ghost".to_string()), 2.0, false, "bravo".to_string());
        assert!(matches!(result, Err(StoreError::NotFound(_))));
    }
}

