using Jig.Domain;

namespace Jig.Application;

/// <summary>Persistence port for contacts. The application depends on this abstraction;
/// Infrastructure supplies the EF Core implementation.</summary>
/// <capability>api.contact-repository-port</capability>
/// <intent>The use-case layer owns the persistence contract it needs, not the database.</intent>
/// <reuse>Depend on IContactRepository from application services; implement it in Infrastructure only.</reuse>
public interface IContactRepository
{
    Task<IReadOnlyList<Contact>> GetAllAsync(CancellationToken ct);
    Task<Contact?> GetByIdAsync(Guid id, CancellationToken ct);
    Task<Contact?> GetByWorkEmailAsync(string workEmail, CancellationToken ct);
    Task<Contact> UpsertAsync(Contact contact, CancellationToken ct);
}

using Jig.Domain;

namespace Jig.Application;

/// <summary>The contact use-cases: list, get, and save. Returns Result envelopes so
/// expected failures travel as data, not exceptions.</summary>
/// <capability>api.contact-service</capability>
/// <intent>One cohesive place for the contact use-case logic, independent of transport and database.</intent>
/// <reuse>Inject ContactService into endpoints; it speaks IContactRepository, never EF Core directly.</reuse>
public sealed class ContactService
{
    private readonly IContactRepository _repo;

    public ContactService(IContactRepository repo) => _repo = repo;

    public async Task<Result<IReadOnlyList<Contact>>> ListAsync(CancellationToken ct)
        => Result<IReadOnlyList<Contact>>.Success(await _repo.GetAllAsync(ct));

    public async Task<Result<Contact>> GetAsync(Guid id, CancellationToken ct)
    {
        var contact = await _repo.GetByIdAsync(id, ct);
        return contact is null ? Error.NotFound($"Contact {id} was not found.") : contact;
    }

    public async Task<Result<Contact>> SaveAsync(Guid? id, string fullName, string workEmail, string homeEmail, CancellationToken ct)
    {
        var byWorkEmail = await _repo.GetByWorkEmailAsync(workEmail, ct);
        if (byWorkEmail is not null && byWorkEmail.Id != id)
            return Error.Conflict($"Work email {workEmail} is already in use.");

        Contact contact;
        if (id is Guid existingId)
        {
            var current = await _repo.GetByIdAsync(existingId, ct);
            if (current is null)
                return Error.NotFound($"Contact {existingId} was not found.");
            current.FullName = fullName;
            current.WorkEmail = workEmail;
            current.HomeEmail = homeEmail;
            contact = current;
        }
        else
        {
            contact = new Contact { Id = Guid.NewGuid(), FullName = fullName, WorkEmail = workEmail, HomeEmail = homeEmail };
        }

        return await _repo.UpsertAsync(contact, ct);
    }
}

