using Jig.Application;
using Jig.Domain;
using Microsoft.EntityFrameworkCore;

namespace Jig.Infrastructure;

/// <summary>EF Core implementation of the contact persistence port.</summary>
/// <capability>api.contact-repository</capability>
/// <intent>The only place that touches EF Core for contacts; the application never sees a DbContext.</intent>
/// <reuse>Registered for IContactRepository by AddInfrastructure; do not new it up directly.</reuse>
public sealed class ContactRepository : IContactRepository
{
    private readonly JigDbContext _db;

    public ContactRepository(JigDbContext db) => _db = db;

    public async Task<IReadOnlyList<Contact>> GetAllAsync(CancellationToken ct)
        => (await _db.Contacts.AsNoTracking().ToListAsync(ct)).OrderBy(x => x.FullName, StringComparer.Ordinal).ThenBy(x => x.Id).ToList();

    public Task<Contact?> GetByIdAsync(Guid id, CancellationToken ct)
        => _db.Contacts.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);

    public Task<Contact?> GetByWorkEmailAsync(string workEmail, CancellationToken ct)
        => _db.Contacts.AsNoTracking().FirstOrDefaultAsync(x => x.WorkEmail == workEmail, ct);

    public async Task<Contact> UpsertAsync(Contact contact, CancellationToken ct)
    {
        var existing = await _db.Contacts.FirstOrDefaultAsync(x => x.Id == contact.Id, ct);
        if (existing is null)
        {
            _db.Contacts.Add(contact);
        }
        else
        {
            existing.FullName = contact.FullName;
            existing.WorkEmail = contact.WorkEmail;
            existing.HomeEmail = contact.HomeEmail;
        }

        await _db.SaveChangesAsync(ct);
        return existing ?? contact;
    }
}

