    let emitted: unknown;
    fixture.componentInstance.saved.subscribe((v) => (emitted = v));

    schemaForm.form().setValue({ fullName: 'alpha', workEmail: 'alpha@x.io', homeEmail: 'alpha@x.io' });
    schemaForm.onSubmit();

    expect(emitted).toEqual({ fullName: 'alpha', workEmail: 'alpha@x.io', homeEmail: 'alpha@x.io' });
  });

  it('does not emit saved when the schema rejects the value', () => {
    const fixture = render();
    const schemaForm = fixture.debugElement.query(By.directive(SchemaForm)).componentInstance as SchemaForm;
    let emitted: unknown;
    fixture.componentInstance.saved.subscribe((v) => (emitted = v));

    schemaForm.form().setValue({ fullName: '', workEmail: 'alpha@x.io', homeEmail: 'alpha@x.io' });
    schemaForm.onSubmit();

