//! Contact store for the desktop client. Holds the same contact use-cases the
//! .NET API does, so the frontend behaves identically whether it talks to the native
//! store or to the API over HTTP. Command adapters are thin wrappers over this; the
//! logic is here and unit-tested in isolation.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Mutex;
use uuid::Uuid;

/// The contact shape crossing the wire. Serializes to the same JSON as the .NET
/// ContactResponse, so the operation registry's res type fits both.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Contact {
    pub id: String,
    pub full_name: String,
    pub work_email: String,
    pub home_email: String,
}

/// An expected failure. Maps to a rejected invoke on the wire.
#[derive(Debug, PartialEq)]
pub enum StoreError {
    NotFound(String),
    Conflict(String),
}

impl std::fmt::Display for StoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StoreError::NotFound(m) | StoreError::Conflict(m) => write!(f, "{m}"),
        }
    }
}

/// In-memory contact store. A template default: swap the Mutex<HashMap> for SQLite or
/// a file store without changing the commands or the frontend.
///
/// @capability shell.contact-store
/// @intent The desktop client's contact use-cases, mirroring the API so both wires agree.
/// @reuse Manage one ContactStore in the app state; commands delegate to it.
#[derive(Default)]
pub struct ContactStore {
    contacts: Mutex<HashMap<String, Contact>>,
}

impl ContactStore {
    pub fn list(&self) -> Vec<Contact> {
        let mut all: Vec<Contact> = self.contacts.lock().unwrap().values().cloned().collect();
        all.sort_by(|a, b| a.full_name.partial_cmp(&b.full_name).unwrap_or(std::cmp::Ordering::Equal).then_with(|| a.id.cmp(&b.id)));
        all
    }

    pub fn get(&self, id: &str) -> Result<Contact, StoreError> {
        self.contacts
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| StoreError::NotFound(format!("Contact {id} was not found.")))
    }

    pub fn save(&self, id: Option<String>, full_name: String, work_email: String, home_email: String) -> Result<Contact, StoreError> {
        let mut contacts = self.contacts.lock().unwrap();

        if let Some(existing) = contacts.values().find(|x| x.work_email == work_email) {
            if Some(&existing.id) != id.as_ref() {
                return Err(StoreError::Conflict(format!("Work email {work_email} is already in use.")));
            }
        }

        match id {
            Some(id) => {
                let contact = contacts
                    .get_mut(&id)
                    .ok_or_else(|| StoreError::NotFound(format!("Contact {id} was not found.")))?;
                contact.full_name = full_name;
                contact.work_email = work_email;
                contact.home_email = home_email;
                Ok(contact.clone())
            }
            None => {
                let contact = Contact { id: Uuid::new_v4().to_string(), full_name, work_email, home_email };
                contacts.insert(contact.id.clone(), contact.clone());
                Ok(contact)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_is_empty_on_a_fresh_store() {
        let store = ContactStore::default();
        assert_eq!(store.list(), vec![]);
    }

    #[test]
    fn save_creates_a_contact_with_an_id() {
        let store = ContactStore::default();
        let contact = store.save(None, "alpha".to_string(), "alpha@x.io".to_string(), "alpha@x.io".to_string()).unwrap();
        assert!(!contact.id.is_empty());
        assert_eq!(contact.full_name, "alpha");
        assert_eq!(store.list().len(), 1);
    }

    #[test]
    fn get_unknown_id_is_not_found() {
        let store = ContactStore::default();
        assert_eq!(
            store.get("missing"),
            Err(StoreError::NotFound("Contact missing was not found.".into()))
        );
    }

    #[test]
    fn save_then_get_roundtrips() {
        let store = ContactStore::default();
        let created = store.save(None, "alpha".to_string(), "alpha@x.io".to_string(), "alpha@x.io".to_string()).unwrap();
        assert_eq!(store.get(&created.id).unwrap(), created);
    }

    #[test]
    fn save_duplicate_work_email_on_a_different_contact_is_conflict() {
        let store = ContactStore::default();
        store.save(None, "alpha".to_string(), "alpha@x.io".to_string(), "alpha@x.io".to_string()).unwrap();
        let result = store.save(None, "bravo".to_string(), "alpha@x.io".to_string(), "bravo@x.io".to_string());
        assert!(matches!(result, Err(StoreError::Conflict(_))));
    }

    #[test]
    fn save_update_keeps_the_same_work_email_without_conflict() {
        let store = ContactStore::default();
        let created = store.save(None, "alpha".to_string(), "alpha@x.io".to_string(), "alpha@x.io".to_string()).unwrap();
        let updated = store
            .save(Some(created.id.clone()), "bravo".to_string(), "alpha@x.io".to_string(), "bravo@x.io".to_string())
            .unwrap();
        assert_eq!(updated.id, created.id);
        assert_eq!(updated.full_name, "bravo");
    }

    #[test]
    fn save_update_of_unknown_id_is_not_found() {
        let store = ContactStore::default();
        let result = store.save(Some("ghost".to_string()), "bravo".to_string(), "bravo@x.io".to_string(), "bravo@x.io".to_string());
        assert!(matches!(result, Err(StoreError::NotFound(_))));
    }
}

