using Jig.Domain;

namespace Jig.Application;

/// <summary>The note use-cases: list, get, and save. Returns Result envelopes so
/// expected failures travel as data, not exceptions.</summary>
/// <capability>api.note-service</capability>
/// <intent>One cohesive place for the note use-case logic, independent of transport and database.</intent>
/// <reuse>Inject NoteService into endpoints; it speaks INoteRepository, never EF Core directly.</reuse>
public sealed class NoteService
{
    private readonly INoteRepository _repo;

    public NoteService(INoteRepository repo) => _repo = repo;

    public async Task<Result<IReadOnlyList<Note>>> ListAsync(CancellationToken ct)
        => Result<IReadOnlyList<Note>>.Success(await _repo.GetAllAsync(ct));

    public async Task<Result<Note>> GetAsync(Guid id, CancellationToken ct)
    {
        var note = await _repo.GetByIdAsync(id, ct);
        return note is null ? Error.NotFound($"Note {id} was not found.") : note;
    }

    public async Task<Result<Note>> SaveAsync(Guid? id, string body, CancellationToken ct)
    {
        Note note;
        if (id is Guid existingId)
        {
            var current = await _repo.GetByIdAsync(existingId, ct);
            if (current is null)
                return Error.NotFound($"Note {existingId} was not found.");
            current.Body = body;
            note = current;
        }
        else
        {
            note = new Note { Id = Guid.NewGuid(), Body = body };
        }

        return await _repo.UpsertAsync(note, ct);
    }
}

