using Jig.Application;
using Jig.Domain;
using Microsoft.EntityFrameworkCore;

namespace Jig.Infrastructure;

/// <summary>EF Core implementation of the note persistence port.</summary>
/// <capability>api.note-repository</capability>
/// <intent>The only place that touches EF Core for notes; the application never sees a DbContext.</intent>
/// <reuse>Registered for INoteRepository by AddInfrastructure; do not new it up directly.</reuse>
public sealed class NoteRepository : INoteRepository
{
    private readonly JigDbContext _db;

    public NoteRepository(JigDbContext db) => _db = db;

    public async Task<IReadOnlyList<Note>> GetAllAsync(CancellationToken ct)
        => (await _db.Notes.AsNoTracking().ToListAsync(ct)).OrderBy(x => x.Body, StringComparer.Ordinal).ThenBy(x => x.Id).ToList();

    public Task<Note?> GetByIdAsync(Guid id, CancellationToken ct)
        => _db.Notes.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);

    public async Task<Note> UpsertAsync(Note note, CancellationToken ct)
    {
        var existing = await _db.Notes.FirstOrDefaultAsync(x => x.Id == note.Id, ct);
        if (existing is null)
        {
            _db.Notes.Add(note);
        }
        else
        {
            existing.Body = note.Body;
        }

        await _db.SaveChangesAsync(ct);
        return existing ?? note;
    }
}

