import type { Observable } from 'rxjs';
import type { SaveNoteInput, NoteDto } from '../contracts';
import { Transport } from '../transport';

/**
 * The note operations facade: speaks operations, never URLs or command names.
 * Identical across both wires because it only ever talks to the Transport port.
 *
 * @capability operations.note
 * @intent Domain-facing note data access that is oblivious to the transport underneath.
 * @reuse Inject NoteOperations from ViewModels; copy this shape for new feature facades.
 */
@Injectable({ providedIn: 'root' })
export class NoteOperations {
  private readonly transport = inject(Transport);

  list(): Observable<NoteDto[]> {
    return this.transport.request('notes.list', {});
  }

  get(id: string): Observable<NoteDto> {
    return this.transport.request('notes.get', { id });
  }

  save(note: SaveNoteInput): Observable<NoteDto> {
    return this.transport.request('notes.save', note);
  }
}

