import { z } from 'zod';
import type { FormFieldMeta } from '../../forms/form-field-meta';

/**
 * The one source of truth for the form that adds notes: shape, validation, and
 * field presentation all live here. The model type is inferred, never hand-written.
 */
export const noteFormSchema = z.object({
  body: z
    .string()
    .min(1, 'Body is required')
    .meta({ label: 'Body', order: 1 } satisfies FormFieldMeta),
});

export type NoteFormModel = z.infer<typeof noteFormSchema>;

import { Component, output } from '@angular/core';
import { SchemaForm } from '../../forms/schema-form';
import { noteFormSchema, type NoteFormModel } from './note-form.schema';

/**
 * The form that adds notes. Renders entirely through SchemaForm: the schema
 * carries every field's shape, validation, and control kind, so this component
 * wires nothing per field and holds no form state of its own.
 */
@Component({
  selector: 'app-note-form',
  imports: [SchemaForm],
  template: `<app-schema-form [schema]="noteFormSchema" submitLabel="Add note" (submitted)="onSubmitted($event)" />`,
})
export class NoteForm {
  protected readonly noteFormSchema = noteFormSchema;
  readonly saved = output<NoteFormModel>();

  // SchemaForm.submitted is output<Record<string, unknown>> because it renders a
  // schema it only knows about at runtime; Angular templates have no `as`, so the
  // narrowing to this form's own model has to happen here rather than inline in the
  // binding above. It only ever emits after safeParse against noteFormSchema (the
  // very schema passed to it above), so the payload is this model by construction.
  protected onSubmitted(value: Record<string, unknown>): void {
    this.saved.emit(value as NoteFormModel);
  }
}

import { computed, inject, provideAppInitializer, type EnvironmentProviders } from '@angular/core';
import { MenuService, navigateCommand, type Command } from '../../menu';
import { NoteListViewModel } from './note-list.view-model';

/** The notes slice's action command: opens the create form, disabled mid-save. */
export function newNoteCommand(vm: NoteListViewModel): Command {
  return {
    id: 'new-note',
    label: 'new note',
    icon: 'lucidePlus',
    canExecute: computed(() => !vm.saving()),
    execute: () => vm.openForm(),
  };
}

/**
 * Registers the notes NAV command app-wide (it must be reachable from anywhere,
 * so it lives for the app's lifetime — provideAppInitializer runs in the root
 * injection context). The ACTION command is registered view-scoped in the view.
 */
export function registerNotesNav(menu: MenuService): void {
  menu.register('sidebar', navigateCommand({ id: 'nav-notes', label: 'notes', icon: 'lucideFile', route: '/notes' }));
}

export function provideNotesMenu(): EnvironmentProviders {
  return provideAppInitializer(() => registerNotesNav(inject(MenuService)));
}

