//! Note store for the desktop client. Holds the same note use-cases the
//! .NET API does, so the frontend behaves identically whether it talks to the native
//! store or to the API over HTTP. Command adapters are thin wrappers over this; the
//! logic is here and unit-tested in isolation.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Mutex;
use uuid::Uuid;

/// The note shape crossing the wire. Serializes to the same JSON as the .NET
/// NoteResponse, so the operation registry's res type fits both.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Note {
    pub id: String,
    pub body: String,
}

/// An expected failure. Maps to a rejected invoke on the wire.
#[derive(Debug, PartialEq)]
pub enum StoreError {
    NotFound(String),
    Conflict(String),
}

impl std::fmt::Display for StoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            StoreError::NotFound(m) | StoreError::Conflict(m) => write!(f, "{m}"),
        }
    }
}

/// In-memory note store. A template default: swap the Mutex<HashMap> for SQLite or
/// a file store without changing the commands or the frontend.
///
/// @capability shell.note-store
/// @intent The desktop client's note use-cases, mirroring the API so both wires agree.
/// @reuse Manage one NoteStore in the app state; commands delegate to it.
#[derive(Default)]
pub struct NoteStore {
    notes: Mutex<HashMap<String, Note>>,
}

impl NoteStore {
    pub fn list(&self) -> Vec<Note> {
        let mut all: Vec<Note> = self.notes.lock().unwrap().values().cloned().collect();
        all.sort_by(|a, b| a.body.partial_cmp(&b.body).unwrap_or(std::cmp::Ordering::Equal).then_with(|| a.id.cmp(&b.id)));
        all
    }

    pub fn get(&self, id: &str) -> Result<Note, StoreError> {
        self.notes
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| StoreError::NotFound(format!("Note {id} was not found.")))
    }

    pub fn save(&self, id: Option<String>, body: String) -> Result<Note, StoreError> {
        let mut notes = self.notes.lock().unwrap();

        match id {
            Some(id) => {
                let note = notes
                    .get_mut(&id)
                    .ok_or_else(|| StoreError::NotFound(format!("Note {id} was not found.")))?;
                note.body = body;
                Ok(note.clone())
            }
            None => {
                let note = Note { id: Uuid::new_v4().to_string(), body };
                notes.insert(note.id.clone(), note.clone());
                Ok(note)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_is_empty_on_a_fresh_store() {
        let store = NoteStore::default();
        assert_eq!(store.list(), vec![]);
    }

    #[test]
    fn save_creates_a_note_with_an_id() {
        let store = NoteStore::default();
        let note = store.save(None, "alpha".to_string()).unwrap();
        assert!(!note.id.is_empty());
        assert_eq!(note.body, "alpha");
        assert_eq!(store.list().len(), 1);
    }

    #[test]
    fn get_unknown_id_is_not_found() {
        let store = NoteStore::default();
        assert_eq!(
            store.get("missing"),
            Err(StoreError::NotFound("Note missing was not found.".into()))
        );
    }

    #[test]
    fn save_then_get_roundtrips() {
        let store = NoteStore::default();
        let created = store.save(None, "alpha".to_string()).unwrap();
        assert_eq!(store.get(&created.id).unwrap(), created);
    }

    #[test]
    fn save_update_of_unknown_id_is_not_found() {
        let store = NoteStore::default();
        let result = store.save(Some("ghost".to_string()), "bravo".to_string());
        assert!(matches!(result, Err(StoreError::NotFound(_))));
    }
}
